/** Exact key path -> [fr, es, ar, zh, ff]. Wins over TRANSLATIONS. */
const KEY_TRANSLATIONS = {};

/**
 * Keys whose stored value reads fine to the detectors but says the wrong thing — "Weekly tips"
 * was translated as advice instead of gratuities, and a receipt tip line kept a stray word.
 */
const FORCE_KEYS = new Set(['driver.menu.tips_week', 'taxi.receipt.fare.tip']);

// ---------------------------------------------------------------------------

const setNested = (obj, keyPath, value) => {
  const parts = keyPath.split('.');
  let cur = obj;
  for (const part of parts.slice(0, -1)) {
    if (!cur[part] || typeof cur[part] !== 'object' || Array.isArray(cur[part])) cur[part] = {};
    cur = cur[part];
  }
  cur[parts.at(-1)] = value;
};
// A short array would silently shift translations into the wrong locale.
const arityErrors = [
  ...Object.entries(TRANSLATIONS).map(([k, v]) => [`TRANSLATIONS[${JSON.stringify(k)}]`, v]),
  ...Object.entries(KEY_TRANSLATIONS).map(([k, v]) => [`KEY_TRANSLATIONS[${JSON.stringify(k)}]`, v]),
].filter(([, v]) => !Array.isArray(v) || v.length !== LOCALES.length);
if (arityErrors.length) {
  console.error(`Expected ${LOCALES.length} values [${LOCALES.join(', ')}] per entry:`);
  arityErrors.forEach(([label, v]) => console.error(`  ${label} has ${v?.length ?? 0}`));
  process.exit(1);
}

const enExtras = readJson('en', 'extras.json');
const en = merged('en');
const enExtrasFlat = flatten(enExtras);
const fr = merged('fr');

const stats = [];
const unresolved = new Map();
const placeholderErrors = [];

for (const [index, locale] of LOCALES.entries()) {
  const common = readJson(locale, 'common.json');
  const extras = readJson(locale, 'extras.json');
  const commonFlat = flatten(common);
  const extrasFlat = flatten(extras);
  const effective = { ...commonFlat, ...extrasFlat };

  let translated = 0;
  let filled = 0;

  for (const [key, enVal] of Object.entries(en)) {
    const current = effective[key];
    const forced = FORCE_KEYS.has(key);
    if (!forced && !needsTranslation({ value: current, enValue: enVal, frValue: fr[key], locale }))
      continue;
    // Sharing the English wording is deliberate here (brand, acronym, symbol).
    if (!forced && current === enVal && isIntentional(enVal, locale)) continue;

    const candidate = KEY_TRANSLATIONS[key]?.[index] ?? TRANSLATIONS[enVal]?.[index] ?? null;
    if (candidate === current) continue;

    if (candidate) {
      if (placeholders(candidate) !== placeholders(enVal)) {
        placeholderErrors.push(`${locale} ${key}: "${enVal}" -> "${candidate}"`);
        continue;
      }
      // extras wins at runtime, so write there unless the key lives only in common.json.
      const target = key in extrasFlat || key in enExtrasFlat || !(key in commonFlat) ? extras : common;
      setNested(target, key, candidate);
      translated += 1;
      continue;
    }

    // No translation needed/available: still materialize the key so the locale file is complete
    // when the English wording is intentionally shared (brands, acronyms, symbols).
    if (current === undefined && (!hasLetters(enVal) || isIntentional(enVal, locale))) {
      const target = key in enExtrasFlat || !(key in commonFlat) ? extras : common;
      setNested(target, key, enVal);
      filled += 1;
      continue;
    }

    if (current === undefined || (hasLetters(enVal) && !isIntentional(enVal, locale))) {
      if (!unresolved.has(enVal)) unresolved.set(enVal, new Set());
      unresolved.get(enVal).add(locale);
    }
  }

  if (!DRY_RUN) {
    fs.writeFileSync(
      path.join(LOCALES_DIR, locale, 'common.json'),
      `${JSON.stringify(common, null, 2)}\n`,
      'utf8',
    );
    fs.writeFileSync(
      path.join(LOCALES_DIR, locale, 'extras.json'),
      `${JSON.stringify(extras, null, 2)}\n`,
      'utf8',
    );
  }
  stats.push({ locale, translated, filled });
}

if (placeholderErrors.length) {
  console.error(`\nPLACEHOLDER MISMATCH (skipped ${placeholderErrors.length}):`);
  placeholderErrors.forEach((e) => console.error(`  ${e}`));
}
if (unresolved.size) {
  console.log(`\nno translation available for ${unresolved.size} string(s):`);
  for (const [value, locs] of unresolved) {
    console.log(`  ${JSON.stringify(value)}\t[${[...locs].join(',')}]`);
  }
}
console.log(`\n${DRY_RUN ? '[dry run] ' : ''}locale | translated | filled`);
for (const { locale, translated, filled } of stats) {
  console.log(`${locale.padEnd(6)} | ${String(translated).padStart(10)} | ${String(filled).padStart(6)}`);
}
console.log(`\nTRANSLATIONS entries: ${Object.keys(TRANSLATIONS).length}`);
